ProjectALife = ProjectALife or {}
ProjectALife.DialogueShards = ProjectALife.DialogueShards or {}
ProjectALife.DialogueShards["scenes_plan_4"] = {
{"fw_ld5_milciv_d028","plan",2,"r1=military|r2=civilian,family,worker,rescue|day=1,10|mood=grim",{1,"Orders were to hold this intersection, nobody's relieved us, shit",2,"So you're just standing here?",1,"Till noon, then we pull back, you can't stay, go to the church, it's got walls"}},
{"fw_ld5_milciv_d029","plan",2,"r1=civilian,family,worker,rescue|r2=military|mood=calm",{1,"You can't take us, can you?",2,"I'm not authorized to take civilians",1,"And?",2,"I'm also not authorized to leave you standing in the road, so get in the truck before I think about it"}},
{"fw_ld5_milciv_d030","plan",2,"r1=family|r2=military|x1=f|day=0,8|mood=fear",{1,"My boy's got a fever, do you have a medic?!",2,"Our medic didn't make it out of the motor pool, ma'am, I'm sorry, I got a first aid kit, an aspirin",1,"An aspirin! That's it?!",2,"That's it, but I'll look at him, hold the flashlight, let him lie down, we'll go from there"}},
{"fw_ld5_milciv_d031","plan",2,"r1=civilian,family,worker,rescue|r2=military|x1=f|day=1,10|mood=angry",{1,"The colonel said no civilians past the goddamn wire, I heard him on the loudspeaker",2,"The colonel's NOT here, ma'am, I am",1,"So?",2,"So I'm taking you to the gate, and if they shoot me for it, put it on my headstone, he tried"}},
{"fw_ld5_milciv_d032","plan",2,"r1=military|r2=civilian,family,worker,rescue|hour=19,4|mood=calm",{1,"We move at night, no talking, I'll use hand signals, tap my shoulder if you need me",2,"What about the kids?",1,"Kids walk between us, hold hands, nobody lets go",2,"They won't be quiet for ten minutes, you know that",1,"They will tonight, I'll tell 'em it's a game, winner gets my chocolate"}},
{"fw_ld5_milciv_d033","plan",2,"r1=military|r2=civilian,family,worker,rescue|x2=f|mood=calm",{1,"Ma'am, where's the nearest clean water? My map's worthless",2,"There's a spring behind the Methodist church, the old pump house",1,"How far?",2,"Half a mile, I'll show you, it comes out cold, my husband used to fill jugs there"}},
{"fw_ld5_milciv_d034","plan",2,"r1=civilian,family,worker,rescue|r2=military|mood=calm",{1,"Is the road to the bridge clear?",2,"I can't give you an all clear. We'd have to look before we go",1,"Then we keep another way in mind",2,"Yeah. Don't let wanting a shortcut decide for us"}},
{"fw_ld5_milciv_d035","plan",2,"r1=military|r2=civilian,family,worker,rescue|x2=f|mood=grim",{1,"Armory's three blocks, ma'am, I'll go in, you wait outside with the kids",2,"Why can't we come?",1,"Because if something's in there, I want it looking at me, NOT at them",2,"...I don't like it, but fine"}},
{"fw_ld5_milciv_d036","plan",2,"r1=military|r2=civilian,family,worker,rescue|day=2,30|mood=funny",{1,"Any of you got food? We ran out of MREs Thursday, I'm living on hope, gum",2,"We got peaches",1,"Peaches! Real ones, in a can? I'll trade you ammo for peaches",2,"Keep your damn ammo, sit down, eat, we're not animals"}},
{"fw_ld5_milciv_d037","plan",2,"r1=civilian,family,worker,rescue|r2=military|x1=f|day=1,10|mood=fear",{1,"What the hell are your orders now, soldier?",2,"Orders were to protect the town, I'm doing that, I'm looking at it",1,"What town? It's three streets and a church!",2,"Then I protect three streets and a church, ma'am, it's what I got"}},
{"fw_ld5_milciv_d038","plan",2,"r1=military|r2=civilian,family,worker,rescue|mood=calm",{1,"You walk behind me, step where I step",2,"Is it mined?",1,"No, but I don't know what's under the weeds, I like my people with all their toes",2,"Behind you, step where you step, got it"}},
{"fw_ld5_milciv_d039","plan",2,"r1=military|r2=civilian,family,worker,rescue|x2=f|hour=6,18|mood=sad",{1,"If I'm not back from the church by dark, wait for nobody, go",2,"That's an awful thing to say",1,"It's a plan, ma'am, it's the kind they teach us",2,"...I'll wait an hour, I don't care what you teach, an hour"}},
{"fw_ld5_milciv_d040","plan",2,"r1=civilian,family,worker,rescue|r2=military|x1=m|day=2,20|mood=calm",{1,"You said you had a squad, where's the rest of 'em?",2,"Water tower, we were supposed to link up Friday, I haven't seen 'em",1,"Then we go to the water tower",2,"We? It's not on your way, sir, you got people to look after"}},
{"fw_ld5_milciv_d041","plan",2,"r1=civilian,family,worker,rescue|r2=military|day=1,14|mood=fear",{1,"Are you gonna shoot if somebody comes at us?!",2,"Only if I have to, damn it",1,"What-- what if you wait too long?",2,"Then I'm slow, and you'll be glad you stayed behind me, c'mon, move"}},
{"fw_ld5_milciv_d042","plan",3,"r1=military|r2=civilian,family,worker,rescue|r3=civilian,family,worker,rescue|mood=calm",{1,"Who here can drive a stick?",2,"I can, just don't let me go fast",3,"I can, and I'll go as fast as I want",1,"Slow one drives, the fast one rides shotgun, I don't need a cowboy in the road",2,"He means you, sit down"}},
{"fw_ld5_milciv_d043","plan",2,"r1=civilian,family,worker,rescue|r2=military|x1=f|day=1,10|mood=angry",{1,"The Army dropped this on us, didn't it?",2,"Ma'am, I don't know what the Army did or didn't do, I know I'm a private who ran out of orders",1,"That's not an answer",2,"It's the only one I got, and I'm still here, so how about we spend the energy getting you to the church"}},
{"fw_ld5_milciv_d044","plan",2,"r1=military|r2=civilian,family,worker,rescue|day=2,30|mood=calm",{1,"If we drive, we keep it slow and stop if we can't see the road. I'll help watch the turns",2,"Slow? We'll be a day getting anywhere",1,"Slow doesn't mean silent. It means I'm not rushing down a road I haven't checked",2,"You call the turns, I drive, I'll holler when I gotta pee"}},
{"fw_ld5_milciv_d045","plan",2,"r1=civilian,family,worker,rescue|r2=military|mood=calm",{1,"Is that a rifle or a stick?",2,"It's a rifle, I'm going to teach you how to hold it, it ain't hard",1,"I don't want to hold it",2,"You don't have to want to, you just have to hold it, right hand here, left hand there"}},
{"fw_ld5_milciv_d046","plan",2,"r1=military|r2=civilian,family,worker,rescue|day=1,14|hour=5,12|mood=fear",{1,"First light, we go to the school, the lieutenant's there, I hope",2,"You hope?!",1,"He said Saturday and it's Tuesday, I don't know, I haven't heard a word",2,"...Then we go, and if he's NOT there, we make a new plan, together"}},
{"fw_ld5_milciv_d047","plan",2,"r1=civilian,family,worker,rescue|r2=military|x1=f|day=2,30|mood=warm",{1,"You're the first person who's told me the truth in a week",2,"The truth is, I don't know, I really don't, I just know where to point the rifle",1,"That's more than most",2,"It's less than I'd like, ma'am, but thank you"}},
{"fw_ld5_milciv_d048","plan",2,"r1=military|r2=civilian,family,worker,rescue|day=3,30|mood=grim",{1,"There's a way through the wire, by the creek, I scouted it",2,"How big a hole?",1,"Big enough for a woman and two kids, not a man with a rifle, damn it",2,"Then the women and the kids go, and I'll hold the rifle on this side"}},
{"fw_ld5_wrkres_d049","plan",2,"r1=worker|r2=rescue|day=1,20|mood=calm",{1,"Plant's got a nurse's station, a stretcher, an oxygen bottle, I got the key",2,"Oxygen? You're sure?",1,"Green bottle on a cart, says medical on it, I walked past it six years",2,"Then that's a stop before the church, bring a hand truck, I need that bottle"}},
{"fw_ld5_wrkres_d050","plan",2,"r1=rescue|r2=worker|mood=calm",{1,"You drove for the county, you know the back roads?",2,"Every one, I plowed 'em, graded 'em, patched 'em, there's a gravel road behind the quarry nobody's heard of",1,"Where the hell's it come out?",2,"By the river, a mile from the boat ramp, I drive, you hold the map"}},
{"fw_ld5_wrkres_d051","plan",2,"r1=worker|r2=rescue|mood=calm",{1,"My goddamn truck's thirsty, there's nothing in the pumps",2,"We got a tank behind the hall, diesel, for the engines",1,"Mine's a gas truck",2,"Then we siphon from the squad truck, it's ugly but it works"}},
{"fw_ld5_wrkres_d052","plan",2,"r1=worker|r2=rescue|day=2,14|mood=angry",{1,"We go back to the damn plant, I'm telling you, the generator ALONE's worth the trip",2,"We go to the clinic, I got three people who need more than a generator",1,"You wanna run a clinic on candles?!",2,"I wanna run it on whatever's in the cabinets, generator second, sorry"}},
{"fw_ld5_wrkres_d053","plan",2,"r1=rescue|r2=worker|mood=calm",{1,"Hydrant on the corner's got pressure from the tower, I could open it if I had the wrench",2,"Pipe wrench in the truck, twenty-four inch",1,"That'll do it, bring buckets, it won't last",2,"I'll bring the wheelbarrow too, I ain't doing this twice"}},
{"fw_ld5_wrkres_d054","plan",2,"r1=rescue|r2=worker|day=0,10|mood=grim",{1,"We need light, a lot of it, I can't work in the dark",2,"I can rig work lights off a car battery, I do it at the plant for night shift",1,"How long?",2,"Twenty minutes, gimme a battery, some wire, don't talk to me"}},
{"fw_ld5_wrkres_d055","plan",2,"r1=rescue|r2=worker|mood=calm|world=door",{1,"If someone couldn't walk, what could we use for a stretcher?",2,"Maybe a door, if we could remove it and it was strong enough",1,"A door?",2,"My granddad used one at the mill. Doesn't mean any door would do; we'd have to check it and work out how to carry it"}},
{"fw_ld5_wrkres_d056","plan",2,"r1=rescue|r2=worker|day=1,14|mood=fear",{1,"Radio in the truck's been calling two days, NOBODY answers",2,"What channel?!",1,"County fire, channel one, I don't know the others",2,"Try the plant channel, we used it for shift change, the foreman's got a base station on his desk"}},
{"fw_ld5_wrkres_d057","plan",2,"r1=worker|r2=rescue|day=2,30|mood=calm",{1,"I'll weld bars on the windows, I got the machine, I just need rod, a generator",2,"We need a way out too, if it goes bad",1,"Bars on the front and a back door with a latch you can open from inside, easy",2,"That's what I like about you, you listen"}},
{"fw_ld5_wrkres_d058","plan",2,"r1=rescue|r2=worker|mood=grim",{1,"We move the hurt by truck, you got a flatbed?",2,"Dually, eight foot, I can throw mattresses on it",1,"Slow, thirty miles an hour tops, nobody should get bounced",2,"Twenty if you want, I hauled eggs for ten years, I know how to go slow"}},
{"fw_ld5_lawmil_d059","plan",2,"r1=law,swat|r2=military|x1=m|mood=calm",{1,"Who's in charge here, soldier? You or me?",2,"With respect, sir, I don't care",1,"That's the right answer",2,"We got one of each, so we split it, I take the bridge, you take the town, we radio when we need the other"}},
{"fw_ld5_lawmil_d060","plan",2,"r1=law|r2=military|day=1,14|mood=calm",{1,"You got rifles, we got a radio that reaches the state post on a good night",2,"Trade you the first for the second, I'm tired of being alone out here",1,"It's a trade",2,"It's a partnership, officer, I'm bringing four guys"}},
{"fw_ld5_lawmil_d061","plan",2,"r1=military|r2=law|mood=grim",{1,"My orders were to hold the damn bridge, so I'm holding it",2,"Against what?",1,"Anything that comes, officer, that's what holding means",2,"Then I'm holding it with you, I'm not leaving a soldier alone on a bridge"}},
{"fw_ld5_lawmil_d062","plan",2,"r1=law,swat|r2=military|x1=m|day=2,20|mood=calm",{1,"Where's your colonel?",2,"Gone Saturday, took half the battalion north, I got the lieutenant's map, a squad",1,"Then you're the colonel",2,"I'm a guy with a map, sir, I'll be colonel if it gets me coffee"}},
{"fw_ld5_lawmil_d063","plan",2,"r1=military|r2=law,swat|mood=calm",{1,"If we had two vehicles, would you want the person who knew the roads in front?",2,"You'd put a cruiser in front?",1,"I'd want the one with the best chance of spotting trouble. Not just the loudest siren",2,"Good. A siren doesn't clear a road just because people used to listen to it"}},
{"fw_ld5_lawmil_d064","plan",2,"r1=law|r2=military|mood=calm",{1,"What's your rifle shoot?",2,"Five-five-six, why?",1,"Mine's nine-millimeter, we got nothing to trade, but we got a pickup full of canned food",2,"Food's better than ammo today, show me the cans"}},
{"fw_ld5_lawmil_d065","plan",2,"r1=law,swat|r2=military|mood=calm",{1,"The Guard armory in Brandenburg, the old man's got a key on a chain",2,"The old man's gone",1,"Key's in his desk, second drawer, I watched him put it there",2,"We get the key, open the damn armory, before anybody else thinks of it"}},
{"fw_ld5_lawmil_d066","plan",2,"r1=law|r2=military|day=3,30|mood=sad",{1,"Your unit pulled out and left you?",2,"Left us to hold the line, then the line went away",1,"That's a hell of a way to get left",2,"Yeah, I'd rather have somebody to hold it with, so, you busy?"}},
{"fw_ld5_reslaw_d067","plan",2,"r1=rescue|r2=law,swat|mood=grim",{1,"We check the houses that burned, there might be people in the cellars",2,"Might, and might not",1,"Might's enough, my chief would've said so",2,"Then we go, and the truck stays running, you hear me, the truck STAYS running"}},
{"fw_ld5_reslaw_d068","plan",2,"r1=law,swat|r2=rescue|day=1,14|mood=sad",{1,"Last thing dispatch said was engine two respond, then nothing",2,"That's, that's us, that's the call we never took",1,"You wanna go now? Tell 'em we're on our way",2,"It's ten days late, but yeah, I'd like to answer it"}},
{"fw_ld5_reslaw_d069","plan",2,"r1=rescue|r2=law|mood=warm",{1,"I'd like to say a few words at the grave before we move on",2,"We don't have much time",1,"Then I'll say a very few",2,"...Take your time, I'll stand guard, I talk to the dead too, every night"}},
{"fw_ld5_eliciv_d070","plan",2,"r1=civilian,family,worker,rescue|r2=elite|day=1,14|mood=fear",{1,"Who are you people? Are you Army?",2,"We're NOT here to answer that",1,"Then why are you helping us?!",2,"You're in the way of where we're going, and I don't like leaving things behind"}},
{"fw_ld5_eliciv_d071","plan",2,"r1=elite|r2=civilian,family,worker,rescue|mood=calm",{1,"We don't stop at the church, we stop at the water",2,"What's the difference?",1,"One has people who ask questions, one has a pump",2,"...Then I'll show you the pump, and I'll keep my questions to myself"}},
{"fw_ld5_eliciv_d072","plan",3,"r1=elite|r2=civilian,family,worker,rescue|r3=civilian,family,worker,rescue|hour=19,5|mood=calm",{1,"We go dark tonight, no fire, no talk",2,"Even whispers?",1,"Whispers carry, nod, point, tap, that's it",3,"What if I need to cough?",1,"Cough into your sleeve and think about how stupid you're being"}},
{"fw_ld5_desciv_d073","plan",2,"r1=civilian,family,worker,rescue|r2=outlaw|day=2,20|mood=fear",{1,"You were Army, why won't you take us to Knox?!",2,"Because I walked off Knox, and they don't forget deserters",1,"It's been a week, they'd forget",2,"They shoot first and remember later, find your own gate"}},
{"fw_ld5_desciv_d074","plan",2,"r1=outlaw|r2=civilian,family,worker,rescue|mood=calm",{1,"You got food, I got a rifle, I walk with you, I eat what you eat",2,"We got eleven mouths, we'll make twelve",1,"And I carry more than I eat, you'll see",2,"...One mistake and you're gone, understand? I'm saying it plain"}},
{"fw_ld5_swatciv_d075","plan",2,"r1=swat|r2=civilian,family,worker,rescue|mood=calm",{1,"Two in front, two in back, you in the middle, nobody ahead of the point",2,"What if you stop?",1,"Then you stop, nobody moves till I raise my hand, understood?",2,"Understood, but I'd feel better if you said it nicer"}},
{"fw_ld5_swatciv_d076","plan",2,"r1=civilian,family,worker,rescue|r2=swat|mood=grim",{1,"The hardware store's locked, can you open it?",2,"I can open anything, I don't know what's behind it",1,"So?",2,"You stand back, I knock first, if something knocks back we go home"}},
{"fw_ld5_mix3_d077","plan",3,"r1=civilian,family,worker,rescue|r2=law,swat|r3=military|x1=f|day=1,14|mood=angry",{1,"So who decides? The cop, the soldier, or me?",2,"I got a badge, but NOBODY's paying me",3,"I got orders, but nobody's giving 'em, damn it",1,"Then I guess I decide, we go to the church, right now",2,"Fine by me",3,"Fine by me, ma'am, you're the first one here with a plan"}},
{"fw_ld5_mix3_d078","plan",3,"r1=law,swat|r2=civilian,family,worker,rescue|r3=civilian,family,worker,rescue|day=2,30|mood=calm",{1,"We sleep in shifts, two hours each, you two first",2,"Where the hell do we sleep?",3,"The pews, I guess",1,"The back pews, away from the windows, keep your shoes on",2,"Shoes on, sleeping in a church, my mother would be thrilled"}},
{"fw_ld5_mix3_d079","plan",3,"r1=military|r2=civilian,family,worker,rescue|r3=law,swat|x2=f|day=1,14|mood=grim",{1,"Bridge is ten miles, we do it in one push, no stopping",2,"Ten miles with a baby?",3,"Ten miles with a baby, ma'am, or we sleep out, take our chances",2,"...Then we do it in one push, but I'm not carrying the bag, somebody else carries the bag",1,"I'll carry the damn bag"}},
{"fw_ld5_mix3_d080","plan",3,"r1=rescue|r2=worker|r3=civilian,family,worker,rescue|day=2,30|mood=calm",{1,"We could float across on three barrels and a door",2,"A raft? You wanna build a raft?",3,"I can't swim",1,"You don't have to swim, you lie on the door, I'll show you",3,"...I'll lie on the door, but if I die I want you to feel guilty"}},
{"fw_ld5_mix3_d081","plan",3,"r1=civilian,family,worker,rescue|r2=civilian,family,worker,rescue|r3=law,swat|mood=funny",{1,"The kid wants to say something",2,"Tell him to say it to the officer, he's got the badge",3,"Go ahead, son, I don't bite",1,"He says there's a shortcut through the cemetery",3,"...I'm not going through a cemetery, but thank him, tell him good thinking"}},
{"fw_ld5_mix3_d082","plan",3,"r1=law,swat|r2=civilian,family,worker,rescue|r3=civilian,family,worker,rescue|x3=f|hour=14,20|mood=calm",{1,"We stop at the Hendersons' for the night, I know the family, they'll take us",2,"What if they're not there?",1,"Then we sleep in their barn, I've done it before, they never knew",3,"You slept in a farmer's barn as a cop?",1,"As a teenager, ma'am, I was a different kind of law then"}},
{"fw_ld5_mix3_d083","plan",3,"r1=family|r2=worker|r3=rescue|mood=calm",{1,"Granddad's cabin's got a well and a woodstove, but it's twelve miles",2,"Twelve miles I can do in the truck, I'll siphon gas on the way",3,"And I got a first aid kit, a good one, in case anybody gets hurt on the way",1,"That's it, we go, we're all going to the cabin, nobody argues",2,"Nobody argues, we got a plan"}},
{"fw_ld5_civlaw_d084","plan",2,"r1=civilian,family,worker,rescue|r2=law,swat|mood=calm",{1,"You're sure about the school?",2,"No",1,"Then why are we going?",2,"Because I'm more sure about it than anything else, and we can't stay here"}},
{"fw_ld5_civlaw_d085","plan",2,"r1=law,swat|r2=civilian,family,worker,rescue|hour=14,19|mood=calm",{1,"What time is it?",2,"Four, maybe, the sun's getting low",1,"Then we find a place before dark, I don't want to be walking when it goes"}},
{"fw_ld5_civlaw_d086","plan",2,"r1=civilian,family,worker,rescue|r2=law|day=1,14|mood=grim",{1,"Is it true the old man's dead?",2,"Hell, I heard that too, I don't know it",1,"Then we don't say it till we know"}},
{"fw_ld5_civlaw_d087","plan",2,"r1=civilian,family,worker,rescue|r2=law,swat|mood=angry",{1,"We agreed on the church, we agreed an hour ago, why are we at the Kroger?!",2,"Because you were hungry, you said, I'm just following the plan, the plan was your stomach",1,"The plan was the CHURCH, I don't care about my stomach",2,"Fine",2,"church, but you owe me an apology, I carried your bag the whole way"}},
{"fw_ld5_civlaw_d088","plan",2,"r1=civilian,family,worker,rescue|r2=law,swat|x2=m|mood=calm",{1,"We should stick to the route, I don't care what's on the side of the road",2,"It's a gas station, we might get fuel",1,"We said no detours, you said it yourself, you made me say it back",2,"I did, I did, I'm sorry, no detours, I'm a man of my word"}},
{"fw_ld5_civlaw_d089","plan",2,"r1=civilian,family,worker,rescue|r2=law,swat|x1=f|mood=funny",{1,"Why are cops always the ones to say we can't?",2,"Because we're the ones who see what happens when you can",1,"That's depressing",2,"It's job security, ma'am, ten more minutes, then we can"}},
{"fw_ld5_civlaw_d090","plan",2,"r1=civilian,family,worker,rescue|r2=law|day=1,10|mood=fear",{1,"Do you hear that?!",2,"Hold still",1,"Is that a car?!",2,"Nobody's driving, it's a dog, a dog with something in its mouth, go around, don't look at it"}},
{"fw_ld5_milciv_d091","plan",2,"r1=civilian,family,worker,rescue|r2=military|x1=f|day=2,30|mood=calm",{1,"What if the Army never comes back?",2,"Then we're the Army, ma'am, somebody has to be",1,"That's not what I meant",2,"I know what you meant, I didn't have a better answer"}},
{"fw_ld5_milciv_d092","plan",2,"r1=military|r2=civilian,family,worker,rescue|mood=calm",{1,"How old a map would you trust? Ten years?",2,"Even a two-year-old gas station map could miss a lot now",1,"Two years is better than ten, though",2,"For road names, maybe. It wouldn't tell you what was waiting on them"}},
{"fw_ld5_milciv_d093","plan",2,"r1=civilian,family,worker,rescue|r2=military|day=1,10|mood=fear",{1,"Are we safe with you?",2,"Safer than without me, damn it",1,"That's not a yes",2,"It's the best I got, but I'm NOT going anywhere, neither's my rifle"}},
{"fw_ld5_wrkres_d094","plan",2,"r1=worker|r2=rescue|mood=angry",{1,"You always do this, you always want to take the long way",2,"The long way's got a pharmacy on it",1,"The short way's got a bridge and no people",2,"No, no people, that's the problem, I need people, I need to know who's still alive"}},
{"fw_ld5_wrkres_d095","plan",2,"r1=rescue|r2=worker|day=2,30|mood=warm",{1,"You're a good man to have around, I want you next to me at the bridge",2,"I'm a guy who knows how to fix a flat",1,"Something's always breaking out there, I want you right next to me when we cross",2,"...Fine, I'm next to you, don't tell the others, I'll have to start being nice"}},
{"fw_ld5_wrkres_d096","plan",2,"r1=worker|r2=rescue|day=3,40|mood=funny",{1,"I vote we find a place with a bathtub",2,"Why the hell a bathtub?",1,"Because I haven't had a bath since the Fourth of July, and I smell like a goat",2,"You smelled like a goat before the Fourth of July, Marty"}},
{"fw_ld5_lawmil_d097","plan",2,"r1=law,swat|r2=military|mood=calm",{1,"You're not what I expected",2,"What the hell did you expect?",1,"A bigger gun, a harder face",2,"I'm a mechanic from Ohio, officer, the gun's borrowed"}},
{"fw_ld5_lawmil_d098","plan",3,"r1=military|r2=law,swat|r3=civilian,family,worker,rescue|x3=f|day=1,14|mood=calm",{1,"Civilians in the middle, deputies on the flanks, soldiers at both ends",2,"That's one cop, one soldier, a bunch of people who can't shoot",3,"I can shoot",2,"...Then you're on the flank, ma'am, God help us all"}},
{"fw_ld5_reslaw_d099","plan",2,"r1=rescue|r2=law,swat|day=2,30|mood=calm",{1,"You always carry that notebook, what's in it?",2,"Names, every address I've checked, every house, who's alive, who's not",1,"That's a lot of names",2,"Somebody's going to want 'em, someday, I wanna be the one who has 'em"}},
{"fw_ld5_eliciv_d100","plan",2,"r1=civilian,family,worker,rescue|r2=elite|x1=f|mood=calm",{1,"You never sleep",2,"I sleep",1,"I've never seen it, who watches while you do?",2,"Nobody, so I do it at noon in the truck, ma'am, ten minutes, don't wake me"}},
{"fw_ld5_swatciv_d101","plan",3,"r1=swat|r2=civilian,family,worker,rescue|r3=civilian,family,worker,rescue|day=1,14|mood=calm",{1,"Stack up behind me, hand on the shoulder of the one in front",2,"Like a conga line?",3,"Don't encourage him",1,"Exactly like a conga line, but quiet, if I stop you stop, no humming"}},
{"fw_ld5_civlaw_d102","plan",2,"r1=civilian,family,worker,rescue|r2=law,swat|day=3,30|mood=funny",{1,"Mrs. Tate made a casserole, she wants the officer to carry it",2,"I'm NOT carrying a casserole into a fight",1,"She says it's for the people at the church, you carry it or she carries it",2,"Hand it over before she decides to bring it herself. Tell her thanks. And that she scares me"}},
{"fw_ld5_civlaw_d103","plan",2,"r1=law,swat|r2=civilian,family,worker,rescue|day=2,30|mood=sad",{1,"We keep a list of who's missing, I need names, ages, where you saw 'em last",2,"What do you do with it?",1,"Hold onto it, in case somebody comes looking, or in case I find somebody",2,"Then put my sister on it, Annie, nineteen, she was at the mall Friday"}},
{"fw_ld5_civlaw_d104","plan",2,"r1=law|r2=civilian,family,worker,rescue|mood=calm",{1,"Everybody gets a whistle, one blast, come to me, two blasts, run",2,"What if I blow it by accident?",1,"Then somebody's mad at you, but they come, that's how it works",2,"I'll hold it in both hands, just in case"}},
{"fw_ld5_civlaw_d105","plan",2,"r1=civilian,family,worker,rescue|r2=law,swat|mood=warm",{1,"My daughter wants to learn the hand signals, the ones you use",2,"Palm out means stop, fist means hold, two fingers means look there",1,"She's eight, she's gonna be bossy with 'em",2,"Let her, I'd rather have a bossy eight-year-old than a quiet one right now"}},
{"fw_ld5_milciv_d106","plan",2,"r1=military|r2=civilian,family,worker,rescue|mood=calm",{1,"Everybody in a line, ten feet apart, I don't care who you are",2,"Why ten feet?",1,"One shot, one problem, not ten, stay in the line, don't bunch up",2,"Ten feet, I can do ten feet, I'll count my steps"}},
{"fw_ld5_milciv_d107","plan",2,"r1=military|r2=civilian,family,worker,rescue|day=2,30|mood=funny",{1,"Any of you cook?",2,"I do, why?",1,"Two weeks of MREs, I'd kill for something that came out of a pot",2,"I got a pot, I got rice, I got half an onion, you're gonna cry"}},
{"fw_ld5_milciv_d108","plan",2,"r1=civilian,family,worker,rescue|r2=military|day=2,30|mood=funny",{1,"What's in the brown bag?",2,"Chili mac, best one, I'm sharing",1,"Why?",2,"You're hungry, and I'm tired of eating ALONE"}},
{"fw_ld5_milciv_d109","plan",2,"r1=military|r2=civilian,family,worker,rescue|x1=m|mood=calm",{1,"I need your truck",2,"What for?",1,"Move the wounded, I'll bring it back, I'll leave you my rifle as collateral",2,"Keep your rifle, sir, take the truck, I just want the keys back, I love that truck"}},
{"fw_ld5_wrkres_d110","plan",2,"r1=worker|r2=rescue|day=2,30|mood=funny",{1,"In the old days we had a lunch whistle, twelve sharp, everybody stopped",2,"We got no whistle",1,"I'll make one, I'll blow it every day at noon",2,"You'll draw every dead thing for a mile",1,"...Okay, a very quiet whistle"}},
{"fw_ld5_wrkres_d111","plan",2,"r1=rescue|r2=worker|mood=calm",{1,"If a pharmacy was locked, would you know how to get in?",2,"I used to be a locksmith before the plant",1,"You're a locksmith?",2,"Six years. Enough to know a bent wire doesn't open every lock in town"}},
{"fw_ld5_wrkres_d112","plan",2,"r1=worker|r2=rescue|day=3,40|mood=calm",{1,"Water tower's got a ladder, a hundred forty feet of it",2,"You wanna climb it?",1,"I wanna see the whole county from the top, find the smoke, find the people",2,"I go first, I'm trained for heights, you hold the bottom, if I fall tell my kids I was brave"}},
{"fw_ld5_wrkres_d113","plan",2,"r1=worker|r2=rescue|day=5,60|mood=calm",{1,"We cut firewood now, in summer, so it's dry by fall",2,"Fall's two months off",1,"Two months is nothing, wood needs six, wet wood's smoke, smoke's a signal",2,"I'll get the saw, you get the ax, a cord by Friday"}},
{"fw_ld5_lawmil_d114","plan",2,"r1=law,swat|r2=military|day=2,30|hour=18,4|mood=calm",{1,"Who sleeps where?",2,"My squad takes the ground floor, your guys the second, civilians the basement",1,"Why civilians in the basement?",2,"If something comes through the front, the basement's the last place it looks"}},
{"fw_ld5_reslaw_d115","plan",2,"r1=law,swat|r2=rescue|day=2,30|mood=sad",{1,"We buried Dutton behind the station, you wanna say something?",2,"I'll say what I can",1,"Say it short, I can't stand long speeches today",2,"...Short's fine, he was a good man, he made good coffee, he's missed"}},
{"fw_ld5_mix3_d116","plan",3,"r1=civilian,family,worker,rescue|r2=worker|r3=law,swat|day=2,30|mood=calm",{1,"Truck's got a bad radiator, we're going nowhere",2,"I can patch it with epoxy and a prayer",3,"How long?",2,"Two hours, and it holds fifty miles, maybe sixty",3,"Fifty's enough, do it, I'll stand watch"}},
{"fw_ld5_civres_d117","plan",2,"r1=rescue|r2=civilian,family,worker,rescue|mood=calm",{1,"Boil the water twenty minutes, then let it cool, every kid drinks a cup",2,"They won't like it",1,"They won't like the other option either, I've seen it"}},
{"fw_ld5_eliciv_d118","plan",2,"r1=elite|r2=law,swat|mood=calm",{1,"We work with you, you don't ask questions",2,"That's not how I work",1,"That's how you work today, or you work alone",2,"...Fine, but I'm writing it in my notebook that I didn't ask"}},
{"fw_ld5_swatciv_d119","plan",2,"r1=swat|r2=civilian,family,worker,rescue|mood=funny",{1,"Your job is to stay behind the armored truck",2,"That's it?",1,"That's it, most important job there is, if you panic everybody panics",2,"I'll stay behind the truck, I'll be the calmest person who ever lived"}},
{"fw_ld5_civres_d120","plan",2,"r1=civilian,family,worker,rescue|r2=rescue|day=2,30|mood=calm",{1,"You wanna run the siren to draw them away from us?",2,"It worked in the drill, the horn pulls 'em off the building",1,"Pulls 'em toward the horn? Is that the idea?",2,"That's the point, then we walk the other way, quiet, in the dark"}},
{"fw_ld5_lawplan_e001","plan",2,"reg=law,swat|day=1,30|mood=calm",{1,"Dutton, you take east, I take west, we meet at the courthouse at noon",2,"East has the school",1,"East has the school and four houses on my list, I trust you with it",2,"Then I'm going, but if I'm late, I'm late, don't come looking"}},
{"fw_ld5_lawplan_e002","plan",2,"reg=law|day=2,30|mood=grim",{1,"We keep the radio on, even if nobody's on it",2,"Why?",1,"Day somebody comes on, I wanna be the one who hears it",2,"...Fine, then I'm bringing batteries, we're low on D cells"}},
{"fw_ld5_lawplan_e003","plan",2,"reg=law,swat|day=1,14|mood=grim",{1,"Somebody's got to find the old man",2,"He went to the Muldraugh substation Friday and NEVER called back",1,"We check the substation, two cars, one stays at the road",2,"If he's in there I'd rather we find him upright"}},
{"fw_ld5_lawplan_e004","plan",2,"reg=law,swat|mood=calm",{1,"Station's got twelve shotguns in the rack and a case of slugs",2,"Twelve guns, we got six people",1,"So six go to anybody who can hold one and don't shake",2,"Hands that don't shake, that's about two people in this town, me included"}},
{"fw_ld5_lawplan_e005","plan",2,"reg=law|day=2,30|mood=calm",{1,"I got a list of old folks living alone, thirty-one names",2,"We can't check thirty-one",1,"Six a day, that's the rotation",2,"I take the first six, I'm bringing cookies, they like it when I bring cookies"}},
{"fw_ld5_lawplan_e006","plan",2,"reg=law,swat|day=2,30|mood=calm",{1,"We run Dixie once a day, north to the river, south to the county line",2,"Looking for what?",1,"People, wrecks with people in them, anything that moves wrong",2,"I drive, you watch, siren stays off, there's no point calling anything in"}},
{"fw_ld5_lawplan_e007","plan",2,"reg=law,swat|day=1,14|mood=grim",{1,"We hold the goddamn courthouse, steel doors, one stairwell, good view of the square",2,"For how long?",1,"Till somebody tells us different, I got no deadline, I got a building",2,"A building's something, Hatcher, it's more than most folks have"}},
{"fw_ld5_lawplan_e008","plan",2,"reg=law|role=law_corrections|day=1,10|mood=grim",{1,"Cells three and four still got men in 'em, two days with no food",2,"We-- we feed 'em, and then what?",1,"Then we decide, I'm not leaving a man to starve in a cell, I don't care what he did",2,"Agreed, I'll get the keys, water first, then food, then we talk"}},
{"fw_ld5_lawplan_e009","plan",2,"reg=law|mood=calm",{1,"Cruiser's on a quarter, we got sixty miles in her, maybe",2,"County garage has a pump",1,"Pump's behind the fence and I don't have the gate key",2,"Bolt cutters in the trunk, we're the law, we cut it, leave a note"}},
{"fw_ld5_lawplan_e010","plan",2,"reg=law|day=3,30|mood=calm",{1,"State police post in E-town, if anybody's left, they'd know where the command is",2,"Twelve miles, through Radcliff",1,"In daylight, two cars, I take the lead, you cover the rear",2,"And if Radcliff's bad?",1,"We turn around and think of something else, nobody's playing the big man today"}},
{"fw_ld5_lawplan_e011","plan",2,"reg=law,swat|day=2,30|mood=grim",{1,"Forty rounds each, that's what we got for this whole county",2,"Forty",1,"We count 'em, we don't waste 'em, we don't fire at something walking away",2,"I'll hold my fire like it's my last paycheck"}},
{"fw_ld5_lawplan_e012","plan",2,"reg=law,swat|day=1,14|mood=calm",{1,"Vests in the locker room, six of 'em, level two",2,"Level two don't stop a rifle",1,"It stops a knife or a bite, which beats nothing",2,"I'll wear one, I'll sweat through it, whatever"}},
{"fw_ld5_lawplan_e013","plan",2,"reg=law|day=2,30|mood=calm",{1,"Four on, four off, I'll write it on the whiteboard",2,"Whiteboard's got my ticket quota on it",1,"I'll erase it, there's no quota anymore",2,"...Say that again, no quota, I might cry"}},
{"fw_ld5_lawplan_e014","plan",2,"reg=law,swat|hour=17,21|mood=calm",{1,"We sleep in the station tonight, cots in back, one man awake at the desk",2,"Who the hell's awake?",1,"Me till two, you till six, I'll wake you with coffee if there's coffee",2,"There's coffee, I hid it behind the toner"}},
{"fw_ld5_lawplan_e015","plan",2,"reg=law|day=2,30|mood=calm",{1,"Evidence locker's got shotgun shells from the Teague case, five boxes",2,"Key's with the property clerk",1,"Property clerk's gone, we cut the damn lock, I'm signing for it",2,"Signing for it, in a notebook, nobody's ever gonna read it, but fine, it's right"}},
{"fw_ld5_lawplan_e016","plan",2,"reg=law,swat|mood=calm",{1,"If we get separated, rally at the Marathon on 31W, I don't care what else is going on",2,"Marathon, got it",1,"I'm not there in two hours, assume I'm not coming",2,"I'll assume nothing, you'll be there, I know you"}},
{"fw_ld5_lawplan_e017","plan",2,"reg=law,swat|day=3,30|mood=calm",{1,"We escort the church people to the farm, twelve miles, two cars up front, one behind",2,"What about the old man in the wheelchair?",1,"Rides in the cruiser, back seat, I'll put a pillow behind him",2,"A pillow, God, it's come to this, I'm a cab driver"}},
{"fw_ld5_lawplan_e018","plan",2,"reg=law|day=2,30|hour=6,18|mood=calm",{1,"Bridge duty, two at a time, eight hours, you watch the west end, I watch the east",2,"Watch for what?",1,"Anybody crossing either way, we don't stop 'em, we just count 'em",2,"Counting people, that's an old man's job, I'm thirty-four"}},
{"fw_ld5_lawplan_e019","plan",2,"reg=law|day=3,40|mood=calm",{1,"State police headquarters is in Frankfort, they'd have orders",2,"Frankfort's sixty miles",1,"Two days if we're careful, and we got the cruiser till the gas runs out",2,"I'd rather know than not know, I say tomorrow, first light"}},
{"fw_ld5_lawplan_e020","plan",2,"reg=law,swat|day=1,14|mood=fear",{1,"What do we tell people? When they ask what's going on?",2,"The truth, what we know",1,"We don't know ANYTHING!",2,"We tell 'em we don't know anything, it's still the truth, they're gonna ask whether we say it or not"}},
{"fw_ld5_lawplan_e021","plan",2,"reg=law|day=2,30|mood=angry",{1,"Radcliff PD hasn't answered in four days, I'm going over there",2,"Alone?!",1,"With you, if you're coming, I need you to cover the car",2,"I'm coming, I just wanted to hear you say it, I hate it when you go off ALONE, damn it"}},
{"fw_ld5_lawplan_e022","plan",2,"reg=law,swat|hour=6,17|mood=calm",{1,"Dairy Bar, then the Marathon, church last if we got daylight left",2,"Why that order?",1,"Because the Dairy Bar's closest, if it's bad we back out, I don't want to be a mile into it when we find out",2,"Dairy Bar, Marathon, church, I'm writing it on my hand"}},
{"fw_ld5_lawplan_e023","plan",2,"reg=law,swat|day=1,14|mood=grim",{1,"If a pharmacy's windows are broken, would you assume it's been stripped?",2,"Looters?",1,"Or scared people. Glass doesn't tell us what's left or who's inside",2,"Then we check what we can see before choosing another place. No guessing there's a nurse waiting elsewhere"}},
{"fw_ld5_lawplan_e024","plan",2,"reg=law|hour=8,23|mood=funny",{1,"What the hell's the plan for tonight?",2,"Plan's to not die",1,"That's a plan?",2,"It's the only one in the handbook, Hatch, I looked"}},
{"fw_ld5_lawplan_e025","plan",2,"reg=law,swat|mood=sad",{1,"I keep thinking about the call that came in right before the radio went",2,"What was it?",1,"A woman, saying a man kept knocking on her door, I told her to lock it, wait for a unit",2,"We didn't have a unit",1,"I-- I know, I think about it, I'm going back to her street tomorrow, I need to see"}},
{"fw_ld5_lawplan_e026","plan",2,"reg=law|day=2,30|mood=calm",{1,"We use ten-codes on the radio, and we keep it short",2,"Why? Nobody's listening",1,"Somebody might be, and if they are, I don't want 'em knowing how many we are",2,"Ten-four, I'll keep it short, it's the first time you've made sense this week"}},
{"fw_ld5_lawplan_e027","plan",2,"reg=law,swat|day=1,10|hour=18,4|mood=fear",{1,"We don't go out at night, nobody does, that's my order",2,"Hell, what if somebody calls?",1,"Nobody's calling, Dutton, the phones are down, who's gonna call?",2,"...Somebody could knock, you ever think about that? I think about that"}},
{"fw_ld5_lawplan_e028","plan",2,"reg=law|mood=calm",{1,"I say we move the station to the high school, it's got a gym, a kitchen, a flagpole",2,"A flagpole, what for?",1,"So somebody sees us, a flag says somebody's still here, I don't care what flag",2,"We've got an American one in the supply closet, I'll bring that"}},
{"fw_ld5_swatplan_e029","plan",2,"reg=swat|day=1,14|mood=calm",{1,"Two on the front, two on the side, I go first, you're second",2,"What the hell's inside?",1,"Nobody knows, that's why we do it in order, slow, no noise",2,"Slow's my middle name"}},
{"fw_ld5_swatplan_e030","plan",2,"reg=swat|mood=calm",{1,"If we ever search a pharmacy, check for another exit before going in",2,"Why worry about another exit?",1,"Because I don't want our only way out behind whatever we find",2,"Copy. But I'm not making noise out front until we've agreed what happens next"}},
{"fw_ld5_swatplan_e031","plan",2,"reg=swat|mood=grim",{1,"We hit the school gym at dawn, entry team goes in first, the rest hold the doors",2,"How many we looking at?",1,"Twenty, thirty, I don't know, I couldn't count from the roof",2,"We go with eight, not six, rally point out front"}},
{"fw_ld5_swatplan_e032","plan",2,"reg=swat|day=2,30|mood=calm",{1,"Breacher's out of charges, we go with the ram",2,"The ram's loud",1,"Everything's loud now, that's why we do it fast, then leave",2,"Fast, I like fast"}},
{"fw_ld5_swatplan_e033","plan",2,"reg=swat|hour=19,4|mood=calm",{1,"We move at night, lights off, I got a pair of goggles for the lead",2,"One pair for the whole team",1,"One pair, the lead wears 'em, the rest follow the shoulder in front",2,"I hate following shoulders, but I'll follow yours"}},
{"fw_ld5_swatplan_e034","plan",2,"reg=swat|day=3,30|mood=funny",{1,"I vote we stop calling it the team and start calling it the crew",2,"Why?",1,"Because team sounds like we're winning, and I don't want to jinx it",2,"...The crew, fine, the crew's going to the church"}},
{"fw_ld5_swatplan_e035","plan",2,"reg=swat|mood=calm",{1,"Nobody moves ahead of the point, ever",2,"Anything else?",1,"Nothing else, just that",2,"Copy, I can handle one rule"}},
{"fw_ld5_milplan_e036","plan",2,"reg=military|day=1,14|mood=grim",{1,"Relief was supposed to be here Saturday, it's Tuesday",2,"Christ, so we hold",1,"We hold till the water's gone, then we move, I'm not dying on a goddamn hill for a schedule",2,"Copy, I'll count the water"}},
{"fw_ld5_milplan_e037","plan",2,"reg=military|mood=funny",{1,"We're out of MREs, we got a case of peaches, a bag of rice",2,"I'll cook the rice",1,"You can cook?",2,"I can boil, Hatch, it's the same thing"}},
}
